import assert from'node:assert/strict';import{mkdirSync,readFileSync,writeFileSync}from'node:fs';import{chromium,webkit}from'playwright';import{chapterCollections}from'../lib/practice-chapters.ts';
const data=JSON.parse(readFileSync('outputs/goal-audit-20261101/inventory.json')),base=process.env.KLINK_TEST_URL||'http://127.0.0.1:18996',out=process.env.KLINK_AUDIT_OUTPUT||'outputs/goal-audit-20261101/interactions';mkdirSync(out,{recursive:true});const map=new Map();for(const c of data.cases)if(!map.has(c.exercise.mode))map.set(c.exercise.mode,c);map.set('content-choice',data.cases.find(c=>c.exercise.mode==='content-choice'&&c.activity==='content-woordpakketten'&&!c.exercise.contentTask.teacherWorkflow));if(process.env.KLINK_MODES)for(const mode of map.keys())if(!process.env.KLINK_MODES.split(',').includes(mode))map.delete(mode);const checks=[],errors=[];
async function click(l){await l.tap();}async function check(p){const c=p.locator('[data-practice-check]:visible:not(:disabled)').filter({hasNotText:'Nu jij'}).first();await click(c);}
async function solve(p,c,scope=p){const e=c.exercise;
 const listen=scope.locator('[data-practice-listen]:visible').first();if(await listen.count()){await click(listen);await p.waitForTimeout(150);}const demo=scope.getByRole('button',{name:'Nu jij',exact:true});if(await demo.count())await click(demo);
 if(e.contentTask){const t=e.contentTask,b=p.getByRole('button',{name:'Begin samen',exact:true});if(await b.count())await click(b);if(t.teacherWorkflow){const field=p.locator('.cp-teacher-workflow textarea:visible').first();if(await field.count())await field.fill('Mijn eigen antwoord.');const step=p.locator('.cp-teacher-workflow [data-practice-check]:visible:not(:disabled)').first();if(await step.count())await click(step);return 'guided-response';}if(t.mode==='choice'){for(const id of t.correctOptionIds)await click(p.locator('.cp-content-task .cp-choice-grid').getByRole('button',{name:t.options.find(o=>o.id===id).text,exact:true}));await check(p);}else{await p.locator('.cp-content-task textarea').fill(t.acceptedAnswers?.[0]||'Mijn eigen antwoord.');await check(p);}return 'answer';}
 const t=e.standardTask;
 if(t){if(t.kind==='sort'){for(const item of t.items){await click(scope.locator(`[data-sort-item="${item.id}"]`));if(t.basis==='sound'){await click(scope.locator('[data-practice-listen]:visible').first());await p.waitForTimeout(100);}await click(scope.locator(`[data-sort-category="${item.categoryId}"]`));}}
 else if(t.kind==='mark'){for(const id of t.acceptedSelections[0])await click(scope.locator(`[data-word-token="${id}"]`));await check(p);}
 else if(t.kind==='gap'){await click(scope.getByRole('button',{name:'Kies een woord',exact:true}));const choice=t.options.find(o=>t.acceptedAnswers.includes(o.label));await click(scope.locator('.cp-choice-grid').getByRole('button',{name:choice.label,exact:true}));}
 else if(t.kind==='hotspot'){const i=t.regions.findIndex(r=>t.correctRegionIds.includes(r.id));await click(scope.locator('.cp-hotspot-list button').nth(i));}
 else if(t.kind==='branch'){let n=t.nodes.find(n=>n.id===t.start);for(let i=0;i<20;i++){const choice=n.choices[0];await click(scope.locator('.cp-branch-options button').first());await click(scope.locator('[data-practice-step-next]'));if(!choice.next)break;n=t.nodes.find(n=>n.id===choice.next);}}return 'answer';}
 if(['word-build','recall-word','sentence-build'].includes(e.mode)){for(const id of e.answer.targetTileIds)await click(scope.locator('.cp-tile-bank > button').nth(e.tiles.findIndex(t=>t.id===id)));}
 else if(['word-image-match','hear-match'].includes(e.mode)){for(const[source,target]of Object.entries(e.answer.mapping)){await click(scope.locator('.cp-match-board > div').first().locator('> button').nth(e.sources.findIndex(s=>s.id===source)));await p.waitForTimeout(100);await click(scope.locator('.cp-match-board > div').last().locator('> button').nth(e.targets.findIndex(t=>t.id===target)));}}
 else if(['copy-word','word-dictation','sentence-dictation'].includes(e.mode)){await scope.locator('.cp-text-entry input').fill(e.fields.flatMap(f=>f.acceptedAnswers||[])[0]);await check(p);}
 else if(['write-word','write-letter','paper-dictation'].includes(e.mode)){await scope.locator('.cp-text-entry input').fill(e.target);await check(p);if(e.hideWritingModel)await check(p);}
 else if(['word-bingo','image-bingo'].includes(e.mode)){await click(scope.locator('.cp-board-grid > button').nth(e.cells.findIndex(cell=>cell.cellId===e.answer.correctCellId)));}
 else if(e.mode==='memory'){const pairs=new Map();e.items.forEach((item,i)=>pairs.set(item.pairKey,[...(pairs.get(item.pairKey)||[]),i]));for(const indexes of pairs.values()){for(const i of indexes)await click(scope.locator('.cp-memory-grid button').nth(i));await p.waitForTimeout(600);}}
 else if(['word-card','synonym-card'].includes(e.mode)){await click(scope.locator('.cp-flash-card'));if(e.cards.length>1)for(let i=0;i<e.cards.length;i++)await click(scope.locator('[data-practice-step-next]'));}
 else if(e.mode==='context-order'){for(const id of e.targetOrderIds)await click(scope.locator(`[data-order-item="${id}"]`));await check(p);}
 else if(['functional-message','functional-form'].includes(e.mode)){if(e.mode==='functional-form'){const options=scope.locator('.cp-sender-choice button');await click(options.first());assert.equal(await options.first().getAttribute('aria-pressed'),'true');await p.waitForTimeout(250);if(await options.count()>1)assert(await options.first().evaluate(e=>getComputedStyle(e).backgroundColor!==getComputedStyle(e.parentElement.querySelector('[aria-pressed="false"]')).backgroundColor),'sender selection needs visible feedback '+JSON.stringify(await options.evaluateAll(es=>es.map(e=>({bg:getComputedStyle(e).backgroundColor,border:getComputedStyle(e).borderColor,pressed:e.getAttribute('aria-pressed')})))));}await scope.locator('textarea').fill(e.writingTask.example);await click(scope.getByRole('button',{name:'Kijk na',exact:true}));for(const box of await scope.locator('.cp-writing-check input').all())await box.check();await click(scope.getByRole('button',{name:'Klaar',exact:true}));}
 else if(['repeat-word','sentence-speak','dialogue-role'].includes(e.mode)){await click(scope.getByRole('button',{name:'Klaar',exact:true}));return 'oral-participation';}
 else if(['model','connected-sentence','connected-text','connected-dialogue','read-series','learning-example'].includes(e.mode)){return 'listening-or-reading';}
 else {const ids=e.answer?.correctOptionIds;if(ids?.length){const options=scope.locator('.cp-choice-grid > button, .cp-choice-grid > .cp-extended-option > button:first-child, .cp-evidence-options > .cp-extended-option > button:first-child');await click(options.nth(e.options.findIndex(o=>ids.includes(o.id))));}else throw Error('No solver '+e.mode);}
 return 'answer';}
for(const[engine,type]of Object.entries({chromium,webkit})){const b=await type.launch();try{for(const c of map.values()){const p=await b.newPage({viewport:engine==='chromium'?{width:390,height:844}:{width:320,height:568},hasTouch:true});p.setDefaultTimeout(15000);const record={engine,mode:c.exercise.mode,activity:c.activity};try{await p.addInitScript(c=>{window.Audio=class extends EventTarget{play(){this.timer=setTimeout(()=>this.dispatchEvent(new Event('ended')),30);return Promise.resolve();}pause(){clearTimeout(this.timer);}};localStorage.setItem(`klink.group.v1:chapter:${c.activity}:${c.collection}:${c.activity}`,JSON.stringify({version:1,done:false,exerciseId:c.exercise.exerciseId}));if(c.activity==='learning-review')localStorage.setItem('klink.learning-review.v1',JSON.stringify({[c.exercise.exerciseId]:{due:0,last:0,streak:0}}));localStorage.setItem('klink.audit.answer-retention','kept');},c);await p.goto(base+c.route);
if(['worksheet','worksheet-heard'].includes(c.activity)){const rows=p.locator('[data-worksheet-exercise]');await rows.first().waitFor();const collection=chapterCollections(c.activity).find(r=>r.id===c.collection);for(const item of await rows.all()){const id=await item.getAttribute('data-worksheet-exercise');await solve(p,{...c,exercise:collection.exercises.find(e=>e.exerciseId===id)},item);}const next=p.locator('.cp-word-worksheet > [data-practice-next]');assert(await next.isEnabled());await click(next);record.next=true;}
else{const root=p.locator('[data-exercise-id]');await root.waitFor();assert.equal(await root.getAttribute('data-exercise-id'),c.exercise.exerciseId);record.response=await solve(p,c);if(record.response==='guided-response'){record.nextWithinWorkflow=true;}else{const next=p.locator('[data-practice-next]');assert(await next.isEnabled(),'Next remains disabled after '+c.exercise.mode);await next.press('Enter');await p.waitForTimeout(100);assert.notEqual(await p.locator('[data-exercise-id]').getAttribute('data-exercise-id').catch(()=>null),c.exercise.exerciseId);record.next=true;}}
assert.equal(await p.evaluate(()=>localStorage.getItem('klink.audit.answer-retention')),'kept');record.storagePreserved=true;checks.push(record);}catch(e){record.error=e.message;errors.push(record);await p.screenshot({path:out+'/'+engine+'-'+c.exercise.mode+'-failed.png'}).catch(()=>{});}finally{await p.close();writeFileSync(out+'/checks.json',JSON.stringify({base,checks,errors},null,2)+'\n');}}}finally{await b.close();}}
console.log(checks.length,'mobile answer/advance flows;',errors.length,'errors');if(errors.length)process.exitCode=1;
